window.RP_SESSION={"id":"S-35357d5efab2","messages":[{"id":"RP-II-0103871","time":"2026-05-28T16:23:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"슬슬 날이 더워지고 있다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103872","time":"2026-05-28T16:23:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103873","time":"2026-05-28T16:23:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0103874","time":"2026-05-28T16:23:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩+1","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103875","time":"2026-05-28T16:23:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[10] + [2] + [1] = [13]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0103876","time":"2026-05-28T16:24:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만 오늘도 할 일은 해야지.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103877","time":"2026-05-28T16:25:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘도 화살은 연달아 명중한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103878","time":"2026-05-28T16:25:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"검은 배우고 있기는 해도 아직 성장할 여지가 많이 남아 있지만, 활 하나만은 역시 자신이 있지.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103879","time":"2026-05-28T16:26:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"팍, 팍, 팍!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103880","time":"2026-05-28T16:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"화살이 표적에 꽂히는 소리가 열두 번 들린다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103881","time":"2026-05-28T16:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"한 다스의 화살을 모조리 표적에 명중시키고 나서야 뿌듯한 표정으로 잠시 그걸 감상하는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103882","time":"2026-05-28T16:27:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"오······ 꽤 잘 쏘네? 팔짱을 끼고 활을 당겨 쏘는 태를 관찰하듯이 구경합니다.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103883","time":"2026-05-28T16:29:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 록시 씨도 화, 활 쏴 보셨어요? \"\n\n활을 다 쏘고 나서 록시에게 다가가 말한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103884","time":"2026-05-28T16:33:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"험··· 딱히? 물론, 석궁같은 거야 멍청한 *끼들 대가리에 몇 번 쏴봤지.\"\n\n레마가 다가오자, 팔짱을 낀 팔을 풀고 뒷짐을 짚은 채 말합니다.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103885","time":"2026-05-28T16:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 하, 한 번 쏴 보실래요? 제가 도, 도와 드릴게요. \"\n\n레마는 록시에게 활을 건내준다. 그리고 평범한 화살 하나도.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103886","time":"2026-05-28T16:36:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"평소처럼 확 받아채고는 씨익 미소를 짓습니다.\n\n\"네가 그리 애걸복걸 빈다면야··· 어쩔 수가 없지. 한 방에 명중시켜 주겠어.\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103887","time":"2026-05-28T16:38:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 좋아요. 자, 다리 사, 살짝 뒤로 벌리고... 화살은 이렇게... \"\n\n활을 쏘는 법과 자세를 하나하나 짚어 주고, 록시의 뒤로 가서... 끌어안는다? 아니, 끌어안는게 아니라 자세를 다시 잡아 주는 것이다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103888","time":"2026-05-28T16:38:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"록시, 민첩!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103889","time":"2026-05-28T16:39:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103890","time":"2026-05-28T16:40:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'록시'의 민첩 판정 :\n[4] + [2] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0103891","time":"2026-05-28T16:40:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"ㅠ","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103892","time":"2026-05-28T16:41:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 다 도, 도와드렸는데... 그럴 수 이, 있죠! \"\n\n실망한 표정. 하지만 금방 다시 헤헤 웃으며 고개를 살짝 기울이는 특유의 제스처를 하며.\n\n\" 록시 씨도 자, 잘 하는게 많으니까요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103893","time":"2026-05-28T16:54:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"그건 그렇지만··· 쳇! 한 번 더. 딱 한 번만 더 하자. 이대로는 *같아서 잠을 못자겠어.\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103894","time":"2026-05-28T16:54:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 좋아요. 그, 그럼 다시 도와 드, 드릴게요. \"\n\n다시 한 번, 준 백허그(?)를 해 주며 자세를 잡아주고, 아까 틀린 자세를 되짚어 주는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103895","time":"2026-05-28T16:54:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"민첩+1!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103896","time":"2026-05-28T16:56:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"!민첩+1","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103897","time":"2026-05-28T16:56:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'록시'의 민첩 판정 :\n[5] + [2] + [1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0103898","time":"2026-05-28T16:56:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"훗. 봤냐?\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103899","time":"2026-05-28T16:56:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 좋아요. 머, 멋지네요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103900","time":"2026-05-28T16:56:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩+1","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103901","time":"2026-05-28T16:56:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[8] + [2] + [1] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0103902","time":"2026-05-28T16:57:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마도 옆에 있던 다른 활을 들어서 딱 맞춘다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103903","time":"2026-05-28T16:57:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 이번에는 호, 혼자 이렇게 쏴 보, 보시겠어요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103904","time":"2026-05-28T16:59:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마, 민첩-1!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103905","time":"2026-05-28T16:59:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"······ 똑바로 보라고!\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103906","time":"2026-05-28T16:59:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103907","time":"2026-05-28T16:59:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'록시'의 민첩 판정 :\n[4] + [2] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0103908","time":"2026-05-28T16:59:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"아.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103909","time":"2026-05-28T16:59:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"쿡. 록시가 귀여워서 웃고 있다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103910","time":"2026-05-28T17:00:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"······ ···무, 무승부로··· 하지 않을래···?\"","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103911","time":"2026-05-28T17:00:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 걱정 마요. 언젠가는 자, 잘 하게 될거에요. \"\n\n아까처럼 록시를 끌어안고 쓰다듬어 준다. 복복복...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103912","time":"2026-05-28T17:00:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 졌으니까 가만히 바, 받아들여요. \"\n\n복복복...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103913","time":"2026-05-28T17:01:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"흥···.\"\n\n가만히 쓰다듬을 받습니다. 웬일로 난리를 치지 않고요. 무척이나 희안한 일입니다···","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103914","time":"2026-05-28T17:01:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"행복을 느낀다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103915","time":"2026-05-28T17:02:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 록시 씨. 지금 지, 진짜 귀여운거 알죠. \"\n\n록시를 쓰다듬으며 헤실거린다. 기분 좋아.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103916","time":"2026-05-28T17:05:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"닥, 닥쳐. ···입 다물고 쓰담기만 하라고.\"\n\n이런 처사가 부끄러운듯, 볼기에 불그스름한 홍조들이 하나둘씩 떠오른다. 도적의··· 수치···.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103917","time":"2026-05-28T17:07:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 기분 나, 나쁜거에요? \"\n\n수치스러워 하는게 너무 귀여워서 쓰다듬는걸 멈출 수가 없다. 깨물어 주고 싶지만 그러면 아파하겠지...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103918","time":"2026-05-28T17:10:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"······.\"\n\n무뚝뚝한 침묵으로 일관. 본능적으로 더 깊히 숨으려 하다가, 레마의 품 속을 향해 더 얼굴을 묻습니다.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103919","time":"2026-05-28T17:12:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"헐.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103920","time":"2026-05-28T17:13:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 예상치 못한 록시의 애정?공세에 잠시 당황하지만 어쨌든 좋으니 좋다. 고 생각하며. 머리 뿐만 아니라 등도 쓸어내려 주며 안심시켜 준다. 겸사겸사 본인도 입에서 미소가 떠나질 않고...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103921","time":"2026-05-28T17:20:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 록시 씨. 제가 조, 좋아서 그러는거에요? \"\n\n등 토닥토닥","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103922","time":"2026-05-28T17:21:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"\"다, 닥쳐!\"\n\n황급히 자신의 실수를 깨닫고··· 레마의 포근한 품을 확 뿌리치고 수치심에 질려 도망칩니다.","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103923","time":"2026-05-28T17:21:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103924","time":"2026-05-28T17:21:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'록시'의 민첩 판정 :\n[12] + [2] = [14]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0103925","time":"2026-05-28T17:22:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어, 어디 가요... \"\n\n쫒지 않고 가만히 손만 뻗는다...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103926","time":"2026-05-28T17:24:00+09:00","room":"RP II","name":"록시","profile":"로버트 해머","identity":"reviewed","type":"dialogue","body":"그녀의 말이 들리지 않는 건지, 뒤도 돌아보지 않은 채 레마의 시야에서 재빨리 사라집니다. 오늘 록시의 잠자리는··· 영 좋지 않을 것이 분명합니다. 또 잠에 들 법하다가도, 또다시 설칠 것이 자명합니다. 특히 누군가에 대한 깊은 고민 때문에요······","characters":["P-eab7cd26db11"]},{"id":"RP-II-0103927","time":"2026-05-28T17:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fon","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103928","time":"2026-05-28T17:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103929","time":"2026-05-28T17:27:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
